const menu=document.querySelector('.menu');menu.addEventListener('click',()=>document.querySelector('.nav nav').classList.toggle('open'));document.querySelectorAll('.nav nav a').forEach(a=>a.addEventListener('click',()=>document.querySelector('.nav nav').classList.remove('open')));document.querySelector('#inquiry-form').addEventListener('submit',e=>{e.preventDefault();document.querySelector('#form-result').textContent='Prototype complete: your enquiry details are entered, but this demo does not send or store them.';});
